// Hand-written `pg` stub for the flowatlas fixture suite. The types carry nothing
// about what is being touched: everything is inside the query string, which is
// why the `pg` descriptor parses the first argument instead of reading a type
// argument.

export interface QueryResult<Row = unknown> {
  rows: Row[];
  rowCount: number;
}

export declare class Pool {
  query<Row = unknown>(sql: string, values?: unknown[]): Promise<QueryResult<Row>>;
  connect(): Promise<PoolClient>;
  end(): Promise<void>;
}

export declare class PoolClient {
  query<Row = unknown>(sql: string, values?: unknown[]): Promise<QueryResult<Row>>;
  release(): void;
}
